+    fn start_visual_selection(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let pane = self.focus;
+        let position = self.selection_start_position(pane, right_content, right_cursor_column);
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+        self.mode = UiMode::Visual;
+    }
+
+    fn set_visual_selection_kind(&mut self, kind: VisualSelectionKind) {
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.kind = kind;
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize, right_content: &str) {
+        let Some(selection) = self.visual_selection.clone() else {
+            return;
+        };
+        let lines = self.visual_lines_for_pane(selection.pane, right_content);
+        if lines.is_empty() {
+            return;
+        }
+        let max_row = lines.len() - 1;
+        let next_row = selection
+            .cursor
+            .row
+            .saturating_add_signed(row_delta)
+            .min(max_row);
+        let line_len = lines[next_row].chars().count();
+        let max_column = line_len.saturating_sub(1);
+        let next_column = if column_delta == 0 {
+            selection.cursor.column.min(max_column)
+        } else {
+            selection
+                .cursor
+                .column
+                .saturating_add_signed(column_delta)
+                .min(max_column)
+        };
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor = TextPosition {
+                row: next_row,
+                column: next_column,
+            };
+        }
+    }
+
+    fn yank_visual_selection(&mut self, right_content: &str, linewise: bool) {
+        if let Some(selection) = self.visual_selection.clone() {
+            let lines = self.visual_lines_for_pane(selection.pane, right_content);
+            let text = selected_text_from_lines(&lines, &selection, linewise);
+            self.store_copied_text(text);
+        }
+        self.mode = UiMode::Command;
+        self.clear_visual_selection();
+    }
+
+    fn yank_focused_line(&mut self, right_content: &str, right_cursor_column: Option<usize>) {
+        let pane = self.focus;
+        let position = self.selection_start_position(pane, right_content, right_cursor_column);
+        let lines = self.visual_lines_for_pane(pane, right_content);
+        if let Some(line) = lines.get(position.row) {
+            let mut text = line.clone();
+            text.push('\n');
+            self.store_copied_text(text);
+        }
+    }
+
+    fn store_copied_text(&mut self, text: String) {
+        self.copied_text = Some(text);
+        self.pending_clipboard_osc.set(true);
+        self.show_status_notice(
+            "copied selection",
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+        if self.mode == UiMode::Visual {
+            self.mode = UiMode::Command;
+        }
+    }
+
+    fn selection_start_position(
+        &self,
+        pane: PaneFocus,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> TextPosition {
+        match pane {
+            PaneFocus::Left => TextPosition {
+                row: self
+                    .control_selected
+                    .min(self.left_display_lines().len().saturating_sub(1)),
+                column: 0,
+            },
+            PaneFocus::Right => {
+                let lines = text_lines(&self.visible_right_content(right_content));
+                let row = lines.len().saturating_sub(1);
+                let line_len = lines
+                    .get(row)
+                    .map(|line| line.chars().count())
+                    .unwrap_or_default();
+                TextPosition {
+                    row,
+                    column: right_cursor_column
+                        .unwrap_or(line_len)
+                        .min(line_len.saturating_sub(1)),
+                }
+            }
+        }
+    }
+
+    fn visual_lines_for_pane(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self
+                .left_display_lines()
+                .into_iter()
+                .map(|line| line.text)
+                .collect(),
+            PaneFocus::Right => text_lines(&self.visible_right_content(right_content)),
+        }
+    }
+
+    fn left_display_lines(&self) -> Vec<PaneLine> {
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        let mut lines = vec![PaneLine {
+            text: if self.control_selected == 0 {
+                "> work-leaf  command".to_string()
+            } else {
+                "  work-leaf  command".to_string()
+            },
+            reversed: false,
+        }];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            let selected = self.control_selected == visible_position + 1;
+            lines.push(PaneLine {
+                text: compact_agent_row(agent, selected, inner_width),
+                reversed: agent.ready,
+            });
+            if !agent.modified_files.is_empty() {
+                lines.push(PaneLine {
+                    text: format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    reversed: false,
+                });
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    lines.push(PaneLine {
+                        text: format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        reversed: false,
+                    });
+                }
+            }
+        }
+        lines
+    }
+
+    fn visual_line_spans(&self, pane: PaneFocus, row: usize, line: &str) -> Spans<'static> {
+        let range = self.visual_selection.as_ref().and_then(|selection| {
+            (self.mode == UiMode::Visual && selection.pane == pane)
+                .then(|| visual_selection_range_for_line(selection, row, line.chars().count(), false))
+                .flatten()
+        });
+        spans_for_selection_range(line, range)
+    }

